	        for (int i = 1; i <= 10; i++) {
	            Thread curThread = new JoinThread(previousThread);
	            curThread.start();
	            previousThread = curThread;
	        }
	    }

	    static class JoinThread extends Thread {
	        private Thread thread;

	        public JoinThread(Thread thread) {
	            this.thread = thread;
	        }

	        @Override
	        public void run() {
	            try {
	                thread.join();
