	                try {
	                    Thread.sleep(1000);
	                } catch (InterruptedException e) {
	                    e.printStackTrace();
	                }
	                super.run();
	            }
	        };
	        //busyThread一直执行死循环
	        Thread busyThread = new Thread() {
	            @Override
	            public void run() {
	                while (true) ;
	            }
	        };
